#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;
uniform sampler2D HistorySampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // Blend the new frame with what the persistent target kept from the previous frames.
    vec3 current = texture(InSampler, texCoord).rgb;
    vec3 history = texture(HistorySampler, texCoord).rgb;
    fragColor = vec4(mix(current, history, 0.85), 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}
